    decreases j-i
    invariant 0<=i<=j+1<=v.Length
    invariant strictNegative(v,j+1,v.Length)
    invariant positive(v[0..i]) 
    invariant isPermutation(v[0..v.Length], old(v[0..v.Length]))
    {
        if(v[i]>=0){
           i:=i+1;
        }
        else if(v[j]>=0){
